let batchThumbnailTail=Promise.resolve();
const batchThumbnailJobs=new Set();
function cancelBatchThumbnail(job){if(job.cancelled)return;job.cancelled=true;job.file=null;job.ownsFile=null;batchThumbnailJobs.delete(job);job.reject(new DOMException('Cancelled','AbortError'));}
function discardObsoleteBatchThumbnails(){for(const job of batchThumbnailJobs)if(!job.ownsFile())cancelBatchThumbnail(job);}
function queueBatchPhotoThumbnail(file,ownsFile){
 let job;
 const result=new Promise((resolve,reject)=>{job={file,ownsFile,resolve,reject,cancelled:false};batchThumbnailJobs.add(job);});
 // A failed or cancelled preview must not poison later jobs. Clearing each
 // stale job's file/owner immediately also avoids retaining discarded batches.
 batchThumbnailTail=batchThumbnailTail.then(async()=>{
  try{
   if(job.cancelled)return;
   if(!job.ownsFile()){cancelBatchThumbnail(job);return;}
   const url=await createBatchPhotoThumbnail(job.file);
   if(job.cancelled)return;
   if(!job.ownsFile()){cancelBatchThumbnail(job);return;}
   job.resolve(url);
  }catch(error){if(!job.cancelled)job.reject(error);}
  finally{batchThumbnailJobs.delete(job);job.file=null;job.ownsFile=null;}
 });
 return result;
}
